DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef(oid) INTO f FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='regional_manual_assignment_check';f:=replace(f,'FOR x IN SELECT * FROM public.trips','SELECT mp.work_hours_weekly,w.regional_profile->''areas''->0->>''timezone'' INTO hours,zone FROM public.workspaces w JOIN public.workspace_members m ON m.workspace_id=w.id AND m.role=''owner'' AND m.removed_at IS NULL AND NOT m.is_contractor JOIN public.member_profiles mp ON mp.user_id=m.user_id WHERE w.id=_ws; IF hours IS NOT NULL AND (NOT public.regional_weekly_contains(hours,lower(interval_value),zone) OR NOT public.regional_weekly_contains(hours,upper(interval_value)-interval ''1 second'',zone)) THEN RAISE EXCEPTION ''Provider operating hours or timezone require review'';END IF; IF EXISTS(SELECT 1 FROM public.vehicles v WHERE v.id=_vehicle AND ((cardinality(v.service_states)>0 AND (NOT _t.pickup_state=ANY(v.service_states) OR NOT _t.dropoff_state=ANY(v.service_states))) OR (cardinality(v.service_counties)>0 AND (NOT _t.pickup_county=ANY(v.service_counties) OR NOT _t.dropoff_county=ANY(v.service_counties))) OR (cardinality(v.service_cities)>0 AND (NOT _t.pickup_city=ANY(v.service_cities) OR NOT _t.dropoff_city=ANY(v.service_cities))) OR (cardinality(v.service_zips)>0 AND (NOT _t.pickup_zip=ANY(v.service_zips) OR NOT _t.dropoff_zip=ANY(v.service_zips))) OR (cardinality(v.service_regions)>0 AND (NOT public.florida_county_region(_t.pickup_county)=ANY(v.service_regions) OR NOT public.florida_county_region(_t.dropoff_county)=ANY(v.service_regions))))) THEN RAISE EXCEPTION ''Retained vehicle geographic boundary does not support both locations'';END IF; IF EXISTS(SELECT 1 FROM public.vehicles WHERE id=_vehicle AND travel_radius_miles IS NOT NULL) THEN RAISE EXCEPTION ''Vehicle radius requires verified distance evidence'';END IF; FOR x IN SELECT * FROM public.trips');EXECUTE f; END $$;